import { useQuery } from '@tanstack/react-query';
import type { Author, DBAuthor } from '~/types/bluebird';
import { sortAuthorsByCustomOrder } from '~/utils/bluebirdAuthors';

const fetchAuthors = async (): Promise<Author[]> => {
  const response = await fetch('/api/bluebird/authors');
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const fetchedAuthors: DBAuthor[] = await response.json();
  return sortAuthorsByCustomOrder(fetchedAuthors.map((d) => d.data));
};

export function useBluebirdAuthors() {
  return useQuery<Author[], Error>({
    queryKey: ['authors'],
    queryFn: fetchAuthors
  });
}
